    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1) if (tbc_t_b0[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    $display("INFO coverage: %0d of 19 checked outputs toggled, %0d of 19 bits", tbc_outs, tbc_bits);
  end endtask
  initial begin
    tb_seed = 11; tb_clk = 0; tb_mis = 0; tb_perr = 0; tb_started = 0; tb_ph = 0; tb_k = 0;
    reset = 0; r1 = 0; r2 = 0; r3 = 0; r4 = 0; reset = 1;
    tbc_t_g1 = 0; tbc_p_g1 = 0; tbc_t_g2 = 0; tbc_p_g2 = 0; tbc_t_g3 = 0; tbc_p_g3 = 0; tbc_t_g4 = 0; tbc_p_g4 = 0; tbc_t_l1 = 0; tbc_p_l1 = 0; tbc_t_l2 = 0; tbc_p_l2 = 0; tbc_t_l3 = 0; tbc_p_l3 = 0; tbc_t_l4 = 0; tbc_p_l4 = 0; tbc_t_mux_out1 = 0; tbc_p_mux_out1 = 0; tbc_t_mux_out2 = 0; tbc_p_mux_out2 = 0; tbc_t_mux_out3 = 0; tbc_p_mux_out3 = 0; tbc_t_mux_out4 = 0; tbc_p_mux_out4 = 0; tbc_t_and_out1 = 0; tbc_p_and_out1 = 0; tbc_t_and_out2 = 0; tbc_p_and_out2 = 0; tbc_t_and_out3 = 0; tbc_p_and_out3 = 0; tbc_t_and_out4 = 0; tbc_p_and_out4 = 0; tbc_t_or_out = 0; tbc_p_or_out = 0; tbc_t_b1 = 0; tbc_p_b1 = 0; tbc_t_b0 = 0; tbc_p_b0 = 0;
    for (tb_cyc = 0; tb_cyc < 200; tb_cyc = tb_cyc + 1) begin
      @(negedge tb_clk);
      reset = (tb_cyc < 4) ? 1'b1 : (tb_rand(0) % 400 == 0);
      if (tb_rand(0) % 6 == 0) r1 = ~r1;
      if (tb_rand(0) % 6 == 0) r2 = ~r2;
      if (tb_rand(0) % 6 == 0) r3 = ~r3;
      if (tb_rand(0) % 6 == 0) r4 = ~r4;
      tb_started = (tb_cyc >= 6);
      #4 tb_ph = 0; tb_compare; tb_props; if (tb_started) tb_cov;
      @(posedge tb_clk); #4 tb_ph = 1; tb_compare; tb_props; if (tb_started) tb_cov;
    end
    tb_cov_report;
    if (tb_mis + tb_perr == 0) $display("ALL TESTS PASSED");
    else $display("FAIL: %0d mismatches, %0d property errors", tb_mis, tb_perr);
    $finish;
  end
endmodule

// ---- reference copy of the golden module (children come from lib/)
 `timescale 1ns / 1ps
module rr_comb_new__ref(reset, clk, r1, r2, r3, r4, g1, g2, g3, g4,
	l1, l2, l3, l4, mux_out1, mux_out2, mux_out3, mux_out4, and_out1, and_out2, and_out3, and_out4, or_out,
	 b1, b0,b1_logic,b0_logic );
    input reset;
	 input clk;
    input r1;
    input r2;
    input r3;
    input r4;
   
	 output g1;
    output g2;
    output g3;
    output g4;

	 output l1, l2, l3, l4;
	 output mux_out1, mux_out2, mux_out3, mux_out4;
	 output and_out1, and_out2, and_out3, and_out4, or_out;
	 output b1, b0;    
	 output b1_logic,b0_logic;
	 
	 reg b1, b0;
	 wire gnt1, gnt2, gnt3, gnt4;
	 
	
	 
	 
	 
	 and a1(and_out1, g1, !g2, !g3, !g4);
	 and a2(and_out2, !g1, g2, !g3, !g4);
	 and a3(and_out3, !g1, !g2, g3, !g4);
	 and a4(and_out4, !g1, !g2, !g3, g4);
	 







	 
	 
	 assign mux_out1 = ( and_out1 )? r1 : l1;
	 assign mux_out2 = ( and_out2 )? r2 : l2;
	 assign mux_out3 = ( and_out3 )? r3 : l3;
	 assign mux_out4 = ( and_out4 )? r4 : l4;
	 







	 
	 
	assign g1 = gnt1 & r1;
	assign g2 = gnt2 & r2;
	assign g3 = gnt3 & r3;
	assign g4 = gnt4 & r4;
	







	
	
	
	assign or_out =  (g1 | g2 | g3 | g4); 
	




	
	
	always @ (g1,g2,g3,g4,or_out)
   	begin
				b1 <= ((g4 & !g3 & !g2 & !g1) | (!g4 & g3 & !g2 & !g1));
				b0 <= ((g4 & !g3 & !g2 & !g1) | (!g4 & !g3 & g2 & !g1));
		end
	
	
	
	
		
	 assign l1 = r1 & !g2 & !g3  & !g4 & ( ((!r3 & !r4) & ( b0 | (!b1 & !r2)) ) | (b1 & ( b0 | !r4))  );
	 assign l2 = r2 & !g1 & !g3  & !g4 & ((!b0 & !r1 & !r4) | (!r1 & !r3 & !r4) | (b1 & b0 & !r1)  | (!b1 & !b0) );
	 assign l3 = r3 & !g2 & !g1  & !g4 & ((!r1 & !r2 & !r4) | (b0 & !r1 & !r2)  | (!b1 & !r2) | (!b1 & b0) );
	 assign l4 = r4 & !g2 & !g3  & !g1 & ((!b1 & !r2 & !r3) | (!r1 & !r2 & !r3) | (!b1 & b0 & !r3) | (b1 & !b0));
	 







	 
	 
	 
	 dff_synch_clr dff1(.clk(clk), .d(mux_out1), .clr(reset), .q(gnt1));
	 dff_synch_clr	dff2(.clk(clk), .d(mux_out2), .clr(reset), .q(gnt2));
	 dff_synch_clr dff3(.clk(clk), .d(mux_out3), .clr(reset), .q(gnt3));
	 dff_synch_clr	dff4(.clk(clk), .d(mux_out4), .clr(reset), .q(gnt4));
	 
	 endmodule
